// Isolated parser regression process: loopback only; no Mongo, secrets or business routes.
const express=require('express'),http=require('node:http'),zlib=require('node:zlib'),assert=require('node:assert/strict');
const app=express();app.use(express.json());app.post('/echo',(req,res)=>res.json(req.body));app.get('/health',(_req,res)=>res.json({ok:true}));app.use((err,_req,res,_next)=>res.status(err.status||500).json({error:'Parser rejected input'}));
function request(port,method,path,bytes){return new Promise((resolve,reject)=>{const req=http.request({hostname:'127.0.0.1',port,method,path,headers:bytes?{'Content-Type':'application/json','Content-Encoding':'gzip'}:{}},res=>{const chunks=[];res.on('data',c=>chunks.push(c));res.on('end',()=>resolve({status:res.statusCode,body:JSON.parse(Buffer.concat(chunks).toString())}));});req.on('error',reject);req.setTimeout(2000,()=>req.destroy(Error('Timeout')));req.end(bytes);});}
(async()=>{const server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));try{const port=server.address().port,gzip=zlib.gzipSync(Buffer.from('{"value":"SYNTHETIC gzip"}'));const valid=await request(port,'POST','/echo',gzip);assert.equal(valid.status,200);assert.equal(valid.body.value,'SYNTHETIC gzip');const invalid=await request(port,'POST','/echo',Buffer.from('not gzip'));assert.equal(invalid.status,400);const trailing=await request(port,'POST','/echo',Buffer.concat([gzip,Buffer.from('invalid trailing bytes')]));assert.ok([200,400].includes(trailing.status));if(trailing.status===200)assert.equal(trailing.body.value,'SYNTHETIC gzip');await new Promise(resolve=>setTimeout(resolve,100));assert.equal((await request(port,'GET','/health')).status,200);console.log(JSON.stringify({valid:valid.status,invalid:invalid.status,trailing:trailing.status,health:200}));}finally{await new Promise(resolve=>server.close(resolve));}})().catch(e=>{console.error(e.stack);process.exitCode=1;});
